16	        public static SourceUserDefinedConversionSymbol CreateUserDefinedConversionSymbol(
17	            SourceMemberContainerTypeSymbol containingType,
18	            Binder bodyBinder,
19	            ConversionOperatorDeclarationSyntax syntax,
20	            bool isNullableAnalysisEnabled,
21	            BindingDiagnosticBag diagnostics)
22	        {
23	            // Dev11 includes the explicit/implicit keyword, but we don't have a good way to include
24	            // Narrowing/Widening in VB and we want the languages to be consistent.
25	            var location = syntax.Type.Location;
26	            string name = OperatorFacts.OperatorNameFromDeclaration(syntax);
27	
28	            if (name == WellKnownMemberNames.CheckedExplicitConversionName)
29	            {
30	                MessageID.IDS_FeatureCheckedUserDefinedOperators.CheckFeatureAvailability(diagnostics, syntax.CheckedKeyword);
31	            }
32	            else if (syntax.CheckedKeyword.IsKind(SyntaxKind.CheckedKeyword))
33	            {
34	                diagnostics.Add(ErrorCode.ERR_ImplicitConversionOperatorCantBeChecked, syntax.CheckedKeyword.GetLocation());
35	            }
36	
37	            var interfaceSpecifier = syntax.ExplicitInterfaceSpecifier;
38	
39	            TypeSymbol explicitInterfaceType;
40	            name = ExplicitInterfaceHelpers.GetMemberNameAndInterfaceSymbol(bodyBinder, interfaceSpecifier, name, diagnostics, out explicitInterfaceType, aliasQualifierOpt: out _);
41	
42	            var methodKind = interfaceSpecifier == null
43	                ? MethodKind.Conversion
44	                : MethodKind.ExplicitInterfaceImplementation;
45	
46	            return new SourceUserDefinedConversionSymbol(
47	                methodKind, containingType, explicitInterfaceType, name, location, syntax, isNullableAnalysisEnabled, diagnostics);
48	        }
49	
50	        // NOTE: no need to call WithUnsafeRegionIfNecessary, since the signature
51	        // is bound lazily using binders from a BinderFactory (which will already include an
52	        // UnsafeBinder, if necessary).
53	        private SourceUserDefinedConversionSymbol(
54	            MethodKind methodKind,
55	            SourceMemberContainerTypeSymbol containingType,
56	            TypeSymbol explicitInterfaceType,
57	            string name,
58	            Location location,
59	            ConversionOperatorDeclarationSyntax syntax,
60	            bool isNullableAnalysisEnabled,
61	            BindingDiagnosticBag diagnostics) :
62	            base(
63	                methodKind,
64	                explicitInterfaceType,
65	                name,
66	                containingType,
67	                location,
68	                syntax,
69	                MakeDeclarationModifiers(methodKind, containingType.IsInterface, syntax, location, diagnostics),
70	                hasAnyBody: syntax.HasAnyBody(),
71	                isExpressionBodied: syntax.IsExpressionBodied(),
72	                isIterator: SyntaxFacts.HasYieldOperations(syntax.Body),
73	                isNullableAnalysisEnabled: isNullableAnalysisEnabled,
74	                diagnostics)
75	        {
76	            CheckForBlockAndExpressionBody(
77	                syntax.Body, syntax.ExpressionBody, syntax, diagnostics);
78	
79	            if (syntax.ParameterList.Parameters.Count != 1)
80	            {
81	                diagnostics.Add(ErrorCode.ERR_OvlUnaryOperatorExpected, syntax.ParameterList.GetLocation());
82	            }
83	
84	            if (IsStatic && (IsAbstract || IsVirtual))
85	            {
86	                CheckFeatureAvailabilityAndRuntimeSupport(syntax, location, hasBody: syntax.Body != null || syntax.ExpressionBody != null, diagnostics: diagnostics);
87	            }
88	
89	            if (syntax.ExplicitInterfaceSpecifier != null)
90	                MessageID.IDS_FeatureStaticAbstractMembersInInterfaces.CheckFeatureAvailability(diagnostics, syntax.ExplicitInterfaceSpecifier);
91	        }
