        /// <summary>
        /// Warn about custom members of an inline array struct that are bypassed by the compiler in favor of
        /// built-in element access and conversion mechanisms.
        /// </summary>
        private void ReportInlineArrayMembersNotUsedWarnings(BindingDiagnosticBag diagnostics)
        {
            CSharpCompilation compilation = DeclaringCompilation;
            TypeSymbol? elementType = TryGetInlineArrayElementField()?.Type;

            foreach (Symbol member in GetMembers())
            {
                switch (member)
                {
                    case PropertySymbol { IsIndexer: true, IsExplicitInterfaceImplementation: false } indexer
